	for (const bad of [[], null, undefined, {}, "x"]) assert.throws(() => computeTax(100, bad), TypeError, String(bad));
	for (const broken of [
		[{ upTo: null, rateBp: -1 }],
		[{ upTo: null, rateBp: 10001 }],
		[{ upTo: null, rateBp: 12.5 }],
		[{ upTo: null, rateBp: "10" }],
