	const shared = createClient({ ttlMs: 0, now: () => 0, fetchImpl: () => gate.promise });
	const p1 = shared.get("http://x/a");
	const p2 = shared.get("http://x/a");
	gate.resolve({ status: 200, body: { list: [1] } });
	const [r1, r2] = await Promise.all([p1, p2]);
